import{_ as l,l as o,o as e,c as s,v as t,p,x as r,d as n,i as d,S as D}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"D / T / JK 对照","description":"","frontmatter":{"title":"D / T / JK 对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/flipflop-types.md","filePath":"cs/flipflop-types.md","lastUpdated":1789023840000}'),c={name:"cs/flipflop-types.md"};function h(T,a,_,E,f,u){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="d-t-jk-对照" tabindex="-1">D / T / JK 对照 <a class="header-anchor" href="#d-t-jk-对照" aria-label="Permalink to &quot;D / T / JK 对照&quot;">​</a></h1><div class="epigraph"><p>边沿记忆只要一种：D 触发器。T 与 JK 是输入端的组合包装，便于计数或旧教材画法，不是另一种物理。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/latch-flipflop">锁存与触发器</a>钉死了电平锁存与边沿 D 触发器。本课不重画主从，也不从异步状态机另起。缺口是：教科书还列 T、JK。后课建立保持、寄存器、FSM 默认 <strong>D</strong>；必须说清另外两种只是 D 加门。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>D：边沿把 \\(Q\\leftarrow D\\)。T：边沿若 \\(T=1\\) 则翻转，否则保持——即 \\(D=T\\oplus Q\\)。JK：沿用 \\(J\\) 置 \\(1\\)、\\(K\\) 置 \\(0\\)、皆 1 则翻转；化为 \\(D=J\\bar Q+\\bar K Q\\)。缺口不是新的存储物理，而是激励表与 D 的等价，避免后课以为 CPU 里混用三种硬核。</p><p>异步置位/清零仍是端口，不改变「同步状态走 D」这一默认。</p><h3 id="jk-不是「功能更强所以更适合-cpu」" tabindex="-1">JK 不是「功能更强所以更适合 CPU」 <a class="header-anchor" href="#jk-不是「功能更强所以更适合-cpu」" aria-label="Permalink to &quot;JK 不是「功能更强所以更适合 CPU」&quot;">​</a></h3><p>JK 能表达的下一态 D 全能表达。多两个输入只增加控制器接线。现代标准单元库以 D FF 为主。把 JK 当更通用的记忆，寄存器堆会画错。</p><p><span class="marginnote">Harris 用激励表互化。计数器可用 T（每位进位时翻转）或 D 接增量器。本课不把主从 JK 的 \\(1s\\) 捕获当主干缺陷清单。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列现态 \\(Q\\)、输入、次态 \\(Q^+\\)，反推 \\(D\\)。带使能的寄存器：\\(D=E\\cdot D_{\\mathrm{in}}+\\bar E\\cdot Q\\)。T 计数：低位 \\(T=1\\)，高位 \\(T=\\) 低位全 1，与后课计数器一致。</p>',11)),(e(),p(D,null,{default:r(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAT%5B%22%E9%94%81%E5%AD%98%20%2F%20%E4%B8%BB%E4%BB%8E%22%5D%20--%3E%20DFF%5B%22%E8%BE%B9%E6%B2%BF%20D%22%5D%0A%20%20DFF%20--%3E%20TFF%5B%22T%20%3D%20D%20%E5%BC%82%E6%88%96%20Q%22%5D%0A%20%20DFF%20--%3E%20JK%5B%22JK%20%E5%8C%96%E6%88%90%20D%22%5D%0A%20%20DFF%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%BB%BA%E7%AB%8B%E4%B8%8E%E4%BF%9D%E6%8C%81%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课时序不等式写在 D 的 \\(t_{su}\\)、\\(t_h\\)、\\(t_{cq}\\) 上。T/JK 的建立时间要把输入端组合算进路径。FSM 下一态逻辑的输出就是各位 D。本课结束「有哪几种触发器」的词条式罗列，把记忆收成一种元件。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲脉冲触发、不把 ECL 之类工艺触发器请进来。不分析 JK 禁止输入（那是 SR 锁存的问题，边沿 JK 已避开）。</p><p>后课默认：同步状态是边沿 D 触发器；T/JK 仅在画计数器时作为简写。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>物理记忆用 D；T、JK 是输入组合。</li><li>激励表把任意下一态化成 D。</li><li>下一课把 D 的采样窗口写成建立与保持。</li><li>出处：Harris and Harris。</li></ul>',7))])}const J=l(c,[["render",h]]);export{B as __pageData,J as default};
